+    margin-top: 1.5rem;
+    padding: 1rem;
+    background: white;
+    border: 1px solid #e5e7eb;
+    border-radius: 8px;
+}
+
+.channel-item {
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+    padding: 0.5rem 0;
+    cursor: pointer;
+}
+
+.channel-item input[type="checkbox"] {
+    width: 18px;
+    height: 18px;
+    accent-color: #6366f1;
+}
+
+/* Expandable Panel */
+.expandable-panel {
+    border: 1px solid #e5e7eb;
+    border-radius: 8px;
+    overflow: hidden;
+    margin-bottom: 1.5rem;
+}
+
+.panel-header {
+    width: 100%;
+    padding: 1rem 1.25rem;
+    background: white;
+    border: none;
+    cursor: pointer;
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    font-weight: 500;
+    font-size: 1rem;
+    color: #374151;
+}
+
+.panel-header:hover {
+    background: #f9fafb;
+}
+
+.expand-icon {
+    font-size: 0.8rem;
+    color: #6b7280;
+}
+
+.panel-body {
+    padding: 1.25rem;
+    background: #f9fafb;
+    border-top: 1px solid #e5e7eb;
+}
+
+/* Two-Factor Section */
+.two-factor-section {
+    margin-bottom: 1.5rem;
+}
+
+.status-indicator {
+    font-size: 0.75rem;
+    padding: 0.2rem 0.5rem;
+    border-radius: 12px;
+    margin-left: 0.5rem;
+}
+
+.status-indicator.enabled {
+    background: #d1fae5;
+    color: #065f46;
+}
+
+.status-indicator.disabled {
+    background: #fee2e2;
+    color: #991b1b;
+}
+
+.last-changed {
+    font-size: 0.85rem;
+    color: #6b7280;
+    margin-top: 0.5rem;
+    padding-left: 1rem;
+}
+
+/* Sessions Table */
+.sessions-section {
+    margin-top: 1.5rem;
+}
+
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    background: white;
+    border-radius: 8px;
+    overflow: hidden;
+    border: 1px solid #e5e7eb;
+}
+
+.sessions-table th {
+    background: #f3f4f6;
+    padding: 0.75rem 1rem;
+    text-align: left;
+    font-weight: 600;
+    font-size: 0.85rem;
+    color: #6b7280;
+    text-transform: uppercase;
+    letter-spacing: 0.05em;
+}
+
+.sessions-table td {
+    padding: 0.75rem 1rem;
+    border-top: 1px solid #e5e7eb;
+    font-size: 0.9rem;
+}
+
+.current-badge {
+    background: #dbeafe;
+    color: #1e40af;
+    padding: 0.2rem 0.6rem;
+    border-radius: 12px;
+    font-size: 0.75rem;
+    font-weight: 500;
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    top: 0;
+    left: 0;
+    right: 0;
+    bottom: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.modal {
+    background: white;
+    padding: 2rem;
+    border-radius: 12px;
+    max-width: 420px;
+    width: 90%;
+    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.2);
+}
+
+.modal h3 {
+    margin: 0 0 1rem 0;
+}
+
+.modal p {
+    color: #6b7280;
+    margin-bottom: 1.5rem;
+}
+
+/* Radio Group */
+.radio-group {
+    display: flex;
+    gap: 1rem;
+    flex-wrap: wrap;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    padding: 0.625rem 1rem;
+    border: 1px solid #e5e7eb;
+    border-radius: 6px;
+    cursor: pointer;
+    transition: all 0.2s;
+}
+
+.radio-label:has(input:checked) {
+    border-color: #6366f1;
+    background: rgba(99, 102, 241, 0.05);
+}
+
+.radio-label input[type="radio"] {
+    accent-color: #6366f1;
+}
+
+/* Live Preview */
+.live-preview {
+    margin-top: 1.5rem;
+}
+
+.preview-box {
+    border: 1px solid #e5e7eb;
+    border-radius: 8px;
+    overflow: hidden;
+    transition: all 0.3s ease;
+}
+
+.preview-box.theme-light {
+    background: #ffffff;
+    color: #1f2937;
+}
+
+.preview-box.theme-dark {
+    background: #1f2937;
+    color: #f3f4f6;
+}
+
+.preview-box.theme-system {
+    background: #f3f4f6;
+    color: #374151;
+}
+
+.preview-box.font-small {
+    font-size: 0.8rem;
+}
+
+.preview-box.font-medium {
+    font-size: 1rem;
+}
+
+.preview-box.font-large {
+    font-size: 1.2rem;
+}
+
+.preview-box.compact .preview-header,
+.preview-box.compact .preview-content {
+    padding: 0.5rem 1rem;
+}
+
+.preview-header {
+    padding: 1rem 1.25rem;
+    font-weight: 600;
+    border-bottom: 1px solid rgba(128, 128, 128, 0.2);
+}
+
+.preview-box.theme-dark .preview-header {
+    border-bottom-color: rgba(255, 255, 255, 0.1);
+}
+
+.preview-content {
+    padding: 1.25rem;
+}
+
+.preview-button {
+    margin-top: 0.75rem;
+    padding: 0.5rem 1rem;
+    background: #6366f1;
+    color: white;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+    font-size: inherit;
+}
+
+/* Error Message */
+.error-message {
+    color: #ef4444;
+    font-size: 0.85rem;
+    margin: 0.5rem 0;
+}
+
+/* Loading */
+.loading {
+    color: #6b7280;
+    font-style: italic;
+}
+
+/* Responsive */
+@media (max-width: 768px) {
+    .settings-dashboard {
+        flex-direction: column;
+    }
+
+    .settings-sidebar {
+        width: 100%;
+        padding: 0.75rem 0;
+    }
+
+    .settings-sidebar ul {
+        display: flex;
+        overflow-x: auto;
+    }
+
+    .settings-sidebar li {
+        white-space: nowrap;
+        border-left: none;
+        border-bottom: 3px solid transparent;
+    }
+
+    .settings-sidebar li.active {
+        border-bottom-color: #818cf8;
+        border-left-color: transparent;
+    }
+}
+

